import json as _json, re as _re, datetime as _dt
from decimal import Decimal as _Dec
from pyspark.sql import types as _T

def _coerce(v, dt):
    if v is None:
        return None
    if isinstance(dt, _T.StringType):
        return _json.dumps(v) if isinstance(v, (dict, list)) else str(v)
    if isinstance(dt, (_T.ByteType, _T.ShortType, _T.IntegerType, _T.LongType)):
        return int(v)
    if isinstance(dt, (_T.FloatType, _T.DoubleType)):
        return float(v)
    if isinstance(dt, _T.DecimalType):
        return _Dec(str(v))
    if isinstance(dt, _T.BooleanType):
        return v if isinstance(v, bool) else str(v).lower() == "true"
    if isinstance(dt, (_T.TimestampType, _T.TimestampNTZType)):
        if isinstance(v, _dt.datetime):
            return v
        try:
            return _dt.datetime.fromisoformat(str(v).replace("Z", "+00:00"))
        except ValueError:
            import pandas as _pd
            return _pd.Timestamp(str(v)).to_pydatetime()
    if isinstance(dt, _T.DateType):
        return v if isinstance(v, _dt.date) else _dt.date.fromisoformat(str(v)[:10])
    return v

def make_df(spark, schema, rows):
    """Small in-memory DataFrame with EXACTLY the real bronze schema."""
    data = [tuple(_coerce((r or {}).get(f.name), f.dataType) for f in schema.fields) for r in (rows or [])]
    return spark.createDataFrame(data, schema)

def _norm(v):
    if isinstance(v, _Dec):
        return float(v)
    if isinstance(v, _dt.datetime):
        return v.strftime("%Y-%m-%d %H:%M:%S")
    if isinstance(v, _dt.date):
        return v.isoformat()
    return v

def _keystr(v):
    if v is None:
        return "<null>"
    s = str(_norm(v))
    return s[:10] if _re.match(r"^\d{4}-\d{2}-\d{2}", s) else s

def values_equal(actual, expected, tol=0.01):
    a = _norm(actual)
    if expected is None:
        return a is None
    if a is None:
        return False
    if isinstance(expected, bool) or isinstance(a, bool):
        return str(a).lower() == str(expected).lower()
    if isinstance(expected, (int, float)):
        try:
            return abs(float(a) - float(expected)) <= max(tol, abs(float(expected)) * 1e-6)
        except (TypeError, ValueError):
            return False
    if _re.match(r"^\d{4}-\d{2}-\d{2}$", str(expected)):
        return _keystr(a) == str(expected)
    return str(a) == str(expected)

def compare_rows(actual_rows, expected_rows, keys, label, expected_count=None, absent_rows=None, tol=0.01):
    """Returns a list of human-readable problems (empty = pass)."""
    problems = []
    if expected_count is not None and len(actual_rows) != int(expected_count):
        problems.append(f"{label}: expected {expected_count} row(s), got {len(actual_rows)}")
    for e in expected_rows or []:
        ks = [k for k in keys if k in e] or [k for k, v in e.items() if isinstance(v, str)]
        ident = {k: e.get(k) for k in ks}
        matches = [r for r in actual_rows if all(_keystr(r.get(k)) == _keystr(e.get(k)) for k in ks)]
        if not matches:
            problems.append(f"{label}: no output row for {ident}")
            continue
        if len(matches) > 1:
            problems.append(f"{label}: {len(matches)} rows for {ident} (grain not unique)")
        r = matches[0]
        for c, v in e.items():
            if c in ks:
                continue
            if c not in r:
                problems.append(f"{label}: column '{c}' missing from output")
            elif not values_equal(r.get(c), v, tol):
                problems.append(f"{label} {ident}: {c} expected {v!r}, got {_norm(r.get(c))!r}")
    for e in absent_rows or []:
        if any(all(_keystr(r.get(k)) == _keystr(v) for k, v in e.items()) for r in actual_rows):
            problems.append(f"{label}: row {e} must be excluded but is present")
    return problems

